int a[N],to[V][LOG_N];
int qpow(int x,int y){
	for(int i=0;i<LOG_N;i++)if(y>>i&1)x=to[x][i];
	return x;
}
struct bitree{
	int cnt[N];
	bitree(){memset(cnt,0,sizeof(cnt));}
	void add(int x,int v){
