#include<iostream>
#include<cstdio>
#include<bitset>
using namespace std;
bitset<15005> bi;
int n,m,v,opt,l,r;
int a[100005],b[100005],dp[1005][50];
int read(){
    int x=0,w=1;
	char c=getchar();
    while (c<'0'||c>'9'){if(c=='-') w=-1; c=getchar(); }
    while (c>='0'&&c<='9') x=x*10+c-'0',c=getchar();
    return x*w;
}
void worked(){
	for(int i=0;i<v;i++){
	    dp[i][0]=i*i*i%v;
	}
	for(int i=1;i<=21;i++){
		for(int j=0;j<v;j++){
		    dp[j][i]=dp[dp[j][i-1]][i-1];
		}
	}
}
void add_egsr(int x,int y){
    while(x<=n){b[x]+=y;x+=x&(-x);}
}
int count(int x){
    int ans=0;
	while(x){ans+=b[x];x-=x&(-x);}
	return ans;
}
int sumcount(int x,int y){
	for(int i=21;i>=0;i--){
	    if(y&(1<<i)){
		    x=dp[x][i];
		}
	}
	return x+1;
}
int main(){
	n=read(),m=read(),v=read();
	worked();
	for(int i=1;i<=n;i++){
		a[i]=read();
	}
	for(int i=1;i<=m;i++){
		opt=read(),l=read(),r=read();
		if(opt==1){
			if(r-l>12){
			    puts("Yuno");
				continue;
			}
			bool pd=false;
			bi.reset();
			bi.set(0,1);
			for(int j=l;j<=r;j++){
				int sum=sumcount(a[j],count(j));
				if((bi&(bi<<sum)).any()){
				    puts("Yuno");
					pd|=1;
					break;
				}
				bi=bi|(bi<<sum);
			} 
			if(!pd){
			    puts("Yuki");
			}
		}
		else{
		    add_egsr(l,1);
			add_egsr(r+1,-1);
		}
	}
	return 0;
}
